const categories=[['Tất cả','✨'],['Puzzle','🧩'],['Casual','⭐'],['Sports','⚽'],['Action','⚡']];
const menu=[['home','nav-home','Trang chủ'],['catalog','nav-game','Game'],['tournament','nav-tournament','Giải đấu'],['leaderboard','nav-leaderboard','Xếp hạng'],['account','nav-account','Tôi']];
const defaultState={page:'home',previous:'home',game:'jigsaw',category:'Tất cả',query:'',credits:0,loggedIn:false,phone:'',favorites:[],played:[],scores:[],joined:false,packageName:'Gói trải nghiệm',transactions:[],selectedPackage:20,paymentMethod:'MoMo',paymentStage:'idle',authStep:'phone',returnAfterLogin:'home',packageTermsAccepted:false,confirmTermsAccepted:false};
let state={...defaultState};
try{const saved=JSON.parse(localStorage.getItem('wiig_v14')||'{}');state={...state,...saved,page:'home',previous:'home',query:''}}catch(e){}
// Lượt chơi chỉ thuộc tài khoản đã đăng nhập; không giữ số dư demo cho khách.
if(!state.loggedIn) state.credits=0;
state.credits=Math.max(0,Number(state.credits)||0);
function save(){try{localStorage.setItem('wiig_v14',JSON.stringify(state))}catch(e){}}
function go(page){if(page===state.page){render();return;}state.previous=state.page;state.page=page;state.query='';save();render();window.scrollTo(0,0)}
function back(){go(state.previous&&state.previous!==state.page?state.previous:'home')}
const FOOTER_ICONS={"nav-home": "<svg viewBox=\"0 0 24 24\" width=\"22\" height=\"22\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.65\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"m3.5 10 8.5-7 8.5 7v9a2 2 0 0 1-2 2H5.5a2 2 0 0 1-2-2z\"/><path d=\"M9 21v-8h6v8\"/></svg>", "nav-game": "<svg viewBox=\"0 0 24 24\" width=\"22\" height=\"22\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.65\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M6.5 8h11a4 4 0 0 1 3.9 3.1l1.1 5.3a3 3 0 0 1-4.9 2.9l-2.5-2.1H8.9l-2.5 2.1a3 3 0 0 1-4.9-2.9l1.1-5.3A4 4 0 0 1 6.5 8Z\"/><path d=\"M7.5 11v5M5 13.5h5\"/><circle cx=\"16.5\" cy=\"12\" r=\".8\" fill=\"currentColor\" stroke=\"none\"/><circle cx=\"19\" cy=\"14.5\" r=\".8\" fill=\"currentColor\" stroke=\"none\"/></svg>", "nav-tournament": "<svg viewBox=\"0 0 24 24\" width=\"22\" height=\"22\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.65\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M7 3h10v7a5 5 0 0 1-10 0z\"/><path d=\"M7 5H4a2 2 0 0 0 0 4h3m10-4h3a2 2 0 0 1 0 4h-3M12 15v4m-4 2h8m-7-2h6\"/></svg>", "nav-leaderboard": "<svg viewBox=\"0 0 24 24\" width=\"22\" height=\"22\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.65\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M5 20v-6m7 6V9m7 11V4\" stroke-linecap=\"round\"/></svg>", "nav-account": "<svg viewBox=\"0 0 24 24\" width=\"22\" height=\"22\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.65\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"8\" r=\"4\"/><path d=\"M4.5 21v-2a7.5 7.5 0 0 1 15 0v2\"/></svg>"};
function nav(){return `<nav class="bottomnav" aria-label="Điều hướng chính">${menu.map(([id,ico,label])=>`<button type="button" class="navbtn ${state.page===id?'active':''}" data-go="${id}" ${state.page===id?'aria-current="page"':''}><span class="wg-footer-icon">${FOOTER_ICONS[ico]}</span><span class="nav-label">${label}</span></button>`).join('')}</nav>`}
function header(){return `<header class="topbar wiig-header">
<div class="header-brand"><div class="header-logo">WiiG</div><div class="header-greeting">Chào mừng trở lại 👋</div></div>
<div class="spacer"></div>
<button class="balance-pill header-credits" data-go="packages" aria-label="Xem lượt chơi">
<svg viewBox="0 0 24 24" width="22" height="22" fill="currentColor" aria-hidden="true"><path d="M6.9 5.2h10.2a4.1 4.1 0 0 1 4 3.2l1.2 6.3a3.3 3.3 0 0 1-5.2 3.3l-2.7-2.1H9.6l-2.7 2.1a3.3 3.3 0 0 1-5.2-3.3l1.2-6.3a4.1 4.1 0 0 1 4-3.2ZM8 8.1a1 1 0 0 0-1 1v1H6a1 1 0 1 0 0 2h1v1a1 1 0 0 0 2 0v-1h1a1 1 0 1 0 0-2H9v-1a1 1 0 0 0-1-1Zm8.4 2a1.25 1.25 0 1 0 0 2.5 1.25 1.25 0 0 0 0-2.5Zm2.5-2a1.25 1.25 0 1 0 0 2.5 1.25 1.25 0 0 0 0-2.5Z"/></svg>
<span>${state.credits} lượt</span></button>
<button class="header-bell" data-go="notifications" aria-label="Thông báo"><svg viewBox="0 0 24 24" width="25" height="25" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9ZM10 21h4"/></svg><i class="notification-dot"></i></button>
</header>`}
function packagesHeader(){return `<header class="packages-topbar"><button class="packages-brand" data-go="home" aria-label="Về trang chủ WiiG"><span>WiiG</span></button><button class="packages-credit-pill" data-go="wallet" aria-label="Xem ví lượt chơi">${FOOTER_ICONS['nav-game']}<span>${state.credits} lượt</span><span class="packages-credit-arrow">›</span></button></header>`}
function section(title,link='',target='catalog'){return `<div class="section-heading"><h2>${title}</h2>${link?`<button class="text-link" data-go="${target}">${link} →</button>`:''}</div>`}
function homeCard(g){return `<article class="game-card"><div class="game-art" data-detail="${g.id}"><img src="${gameArt(g)}" alt="${g.name}" loading="lazy"><span class="play-chip">🟡 ${g.cost} lượt</span></div><div class="game-card-body"><h3 data-detail="${g.id}">${g.name}</h3><div class="game-meta"><span>${g.category}</span><b>★ ${g.rating}</b></div><button class="btn purple" data-play-game="${g.id}">▶ Chơi ngay</button></div></article>`}
function leaderboardRows(){let rows=[{name:'DragonKnight',score:12480,avatar:'avatar1'},{name:'MoonLily',score:11960,avatar:'avatar2'},{name:'Bạn',score:state.scores.reduce((a,b)=>a+b.score,0)||10320,avatar:'avatar3'}];return `<div class="rank-list">${rows.map((r,i)=>`<div class="rank-row ${i===2?'rank-me':''}"><span class="rank-position rank-position-${i+1}">${i===0?'👑':i+1}</span><img class="rank-avatar" src="${A(r.avatar)}" alt=""><span class="name">${r.name}</span><span class="score">${r.score.toLocaleString('en-US')} <span class="rank-cup">🏆</span></span></div>`).join('')}</div>`}
function home(){return `<div class="banner"><div class="banner-text"><span class="banner-tag">🎮 7 trò chơi</span><h1>Khám phá<br>thế giới game</h1><p>7 game hấp dẫn, giải đấu và phần thưởng mỗi ngày đang chờ bạn!</p><div class="banner-actions"><button class="btn white" data-go="catalog">▶ Chơi ngay</button><button class="btn ghost" data-go="catalog">Xem game →</button></div><div class="dots"><span></span><span></span><span></span></div></div><img class="banner-art" src="${A('hero')}" alt="Nhân vật 3D WiiG"></div>
${section('Danh mục game')}<div class="category-grid">${[['Puzzle','puzzle'],['Casual','casual'],['Sports','sports'],['Action','action']].map(([name,img])=>`<button class="category-tile" data-category="${name}"><img src="${A(img)}" alt="">${name}</button>`).join('')}</div>
${section('Game nổi bật','Xem tất cả','catalog')}<div class="game-grid">${games.slice(0,4).map(homeCard).join('')}</div>
${section('Giải đấu nổi bật','Xem tất cả','tournament')}<div class="tournament-card"><img src="${A('trophy')}" alt="Cúp giải đấu"><div><span class="status">● Đang mở</span><h3>Speed Challenge</h3><p>Thử thách tốc độ, săn điểm cao, nhận phần thưởng hấp dẫn.</p><button class="btn purple" data-go="tournament">Tham gia ngay →</button></div><button class="btn ghost" style="color:#7137f5;border-color:#e0d7ff" data-go="tournament">Xem giải đấu →</button></div>
<div class="promo promo-credits"><img class="promo-coin-art" src="assets/coins-cutout.png" alt="Xu lượt chơi WiiG"><div class="promo-copy"><span class="promo-tag">Gói lượt chơi</span><h3>20 lượt chơi</h3><p><span class="promo-infinity">∞</span> Cộng dồn, không hết hạn</p></div><button class="btn purple" data-go="packages">Mua gói →</button></div>
${section('Bảng xếp hạng','Xem tất cả','leaderboard')}${leaderboardRows()}`}
function catalog(){let q=state.query.trim().toLowerCase();let list=games.filter(g=>(state.category==='Tất cả'||g.category===state.category)&&(!q||(g.name+' '+g.category).toLowerCase().includes(q)));return `<div class="page-title"><button class="back" data-back>‹</button><div><h1>Danh mục game</h1><p>Tìm game bạn yêu thích</p></div></div><label class="search">⌕ <input id="search" placeholder="Tìm tên game, thể loại..." value="${esc(state.query)}" autocomplete="off"></label><div class="filters" id="filters">${categories.map(([name,icon])=>`<button class="${state.category===name?'active':''}" data-category="${name}">${icon} ${name}</button>`).join('')}</div><div class="catalog-grid" id="catalog-grid">${list.length?list.map(catalogCard).join(''):'<div class="empty">Không có game phù hợp. Hãy chọn danh mục khác.</div>'}</div>`}
function catalogCard(g){return `<article class="catalog-card"><img src="${gameArt(g)}" alt="${g.name}" loading="lazy"><h3>${g.name}</h3><p>${g.category} <span style="float:right;color:#efae00">🟡 ${g.cost} lượt</span></p><button class="btn purple" data-play-game="${g.id}">▶ Chơi ngay</button></article>`}
function detail(){const g=games.find(x=>x.id===state.game)||games[0];const high=Math.max(0,...state.scores.filter(s=>s.id===g.id).map(s=>s.score));const isSpace=false;const steps=isSpace?['Di chuyển và sắp xếp các khối để ghi điểm.','Tạo chuỗi kết hợp để nhận thêm điểm thưởng.','Trò chơi kết thúc khi không còn nước đi phù hợp.']:(g.how||['Chạm hoặc kéo để điều khiển trong trò chơi.','Hoàn thành thử thách để nhận điểm thưởng.','Đạt điểm cao và leo bảng xếp hạng.']);return `<div class="detail-page detail-figma-v41"><div class="detail-top"><button class="detail-back" data-back aria-label="Quay lại"><svg viewBox="0 0 24 24"><path d="m15 5-7 7 7 7"/></svg></button><div><h1>Chi tiết game</h1><p>Khám phá trò chơi yêu thích</p></div></div><img class="detail-cover" src="${gameArt(g)}" alt="${g.name}"><div class="detail-heading"><div><h1>${g.name}</h1><div class="detail-tags"><span>${g.category}</span><span>H5</span></div></div><button class="heart ${state.favorites.includes(g.id)?'liked':''}" data-action="favorite" aria-label="Yêu thích">${state.favorites.includes(g.id)?'♥':'♡'}</button></div><p class="desc">${isSpace?'Trò chơi xếp khối vui nhộn với thử thách phản xạ và tư duy.':g.desc}</p><div class="detail-stats"><div class="detail-stats-main"><div class="detail-stat"><span class="detail-icon orange"><svg viewBox="0 0 24 24"><path d="m12 2 2.7 6.4 6.9.6-5.2 4.6 1.6 6.8L12 17l-6 3.4 1.6-6.8L2.4 9l6.9-.6Z"/></svg></span><div><small>Mỗi lần bắt đầu</small><strong>${g.cost} lượt</strong></div></div><div class="detail-stat"><span class="detail-icon violet"><svg viewBox="0 0 24 24"><rect x="3" y="4" width="18" height="16" rx="2"/><path d="M3 10h18M8 15h8"/></svg></span><div><small>Số dư</small><strong>${state.credits} lượt</strong></div></div></div><div class="detail-stats-side"><div class="detail-stat"><span class="detail-icon mint"><svg viewBox="0 0 24 24"><path d="M7 3h10v8a5 5 0 0 1-10 0V3ZM7 5H4a2 2 0 0 0 0 4h3m10-4h3a2 2 0 0 1 0 4h-3M12 16v4m-4 1h8"/></svg></span><div><small>Điểm cao nhất</small><strong>${high.toLocaleString('vi-VN')}</strong></div></div><button class="detail-rank-link" data-detail-ranking>Xem bảng điểm <span>›</span></button></div></div><div class="detail-instructions"><h3>Cách chơi</h3>${steps.map((t,i)=>`<div class="detail-step"><span class="detail-step-number">${i+1}</span><img src="${A('step'+(i+1))}" alt="Minh họa bước ${i+1}"><p>${t}</p></div>`).join('')}</div><div class="detail-play-footer"><p><span>★</span> Nhấn Chơi ngay sẽ trừ <b>${g.cost} lượt</b>.</p><button class="btn purple block" data-action="play"><svg viewBox="0 0 24 24" fill="currentColor"><path d="m7 4 13 8-13 8z"/></svg> Chơi ngay</button></div></div>`}
function tournament(){return `<div class="page-title"><button class="back" data-back>‹</button><div><h1>Giải đấu</h1><p>Thử thách bản thân và nhận thưởng</p></div></div><div class="tournament-card" style="margin:20px 0"><img src="${A('trophy')}" alt=""><div><span class="status">● Đang mở đăng ký</span><h3>Speed Challenge</h3><p>Thi đấu cùng cộng đồng WiiG · 1 lượt tham gia</p><button class="btn purple" data-action="join">${state.joined?'✓ Đã đăng ký':'Đăng ký giải đấu →'}</button></div></div>${section('Bảng xếp hạng','Xem tất cả','leaderboard')}${leaderboardRows()}${section('Trò chơi thi đấu')}<div class="game-grid">${games.slice(0,4).map(homeCard).join('')}</div>`}

