function rankNavigate(page){state.rankStack=state.rankStack||[];if(state.page!==page)state.rankStack.push(state.page);go(page)}
function rankBack(){const dest=(state.rankStack||[]).pop()||'leaderboard';go(dest)}
function rankSvg(name){const icons={
clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l4 2"/>',
game:'<path d="M6 7h12a4 4 0 0 1 4 3l1 5a3 3 0 0 1-5 3l-3-2H9l-3 2a3 3 0 0 1-5-3l1-5a4 4 0 0 1 4-3Z"/><path d="M7 10v5M4.5 12.5h5"/><circle cx="17" cy="11" r=".8"/><circle cx="19" cy="13" r=".8"/>',
trophy:'<path d="M7 3h10v8a5 5 0 0 1-10 0Z"/><path d="M7 5H4a2 2 0 0 0 0 4h3m10-4h3a2 2 0 0 1 0 4h-3M12 16v4m-4 1h8"/>',
calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4M17 3v4M3 10h18"/>',
location:'<path d="M20 10c0 5-8 12-8 12S4 15 4 10a8 8 0 1 1 16 0Z"/><circle cx="12" cy="10" r="2.5"/>',
chart:'<path d="M5 20v-6m7 6V9m7 11V4"/>',
star:'<path d="m12 2 3 6 6.7 1-4.8 4.7 1.2 6.7L12 17l-6.1 3.4 1.2-6.7L2.3 9 9 8Z"/>',
chevron:'<path d="m9 5 7 7-7 7"/>',
check:'<path d="m5 12 4 4L19 6"/>'
};return `<svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.star}</svg>`}
function rankTop(title,subtitle='',backButton=false,history=true){return `<div class="rank-heading">${backButton?'<button class="rank-back" data-rank-back aria-label="Quay lại">‹</button>':''}<div class="rank-heading-text"><h1>${title}</h1>${subtitle?`<p>${subtitle}</p>`:''}</div>${history?`<button class="rank-history-link" data-rank-go="rankHistory">${rankSvg('clock')} <span>Lịch sử xếp hạng</span> ${rankSvg('chevron')}</button>`:''}</div>`}
function rankTabs(key,values){return `<div class="rank-tabs">${values.map(([value,label,ico])=>`<button class="${(state[key]||values[0][0])===value?'selected':''}" data-rank-setting="${key}" data-rank-value="${value}">${ico?rankSvg(ico):''}${label}</button>`).join('')}</div>`}
function rankBoardRows(count=5,kind='game'){const rows=rankPeople.slice(0,count);return `<div class="rank-table"><div class="rank-table-head"><span>#</span><span>Người chơi</span><span>Tổng điểm</span>${kind==='detail'?'<span>Thời gian đạt</span>':''}</div>${rows.map((p,i)=>`<div class="rank-table-row"><span class="rank-index">${i+4}</span><img src="${A(p.avatar)}" alt=""><span class="rank-person">${p.name}</span><strong>${rankNumber(kind==='tournament'?Math.round(p.score*.265):p.score)}</strong>${kind==='detail'?`<small>12/10 20:14</small>`:''}</div>`).join('')}<div class="rank-table-row me"><span class="rank-index">${kind==='detail'?12:8}</span><img src="${A('rank-avatar4')}" alt=""><span class="rank-person">Bạn <small>✓ Vị trí của bạn</small></span><strong>${rankNumber(kind==='detail'?4580:10320)}</strong>${kind==='detail'?'<small>12/10 13:32</small>':''}</div></div>`}
function rankPodium(){return `<div class="rank-podium"><img src="${A('rank-podium')}" alt="Top 3: Minh Anh hạng 2, Hoàng Nam hạng 1, Tuấn Kiệt hạng 3"></div>`}
function rankGameCards(){return `<div class="rank-game-cards">${rankGames.slice(0,3).map((g,i)=>`<button class="rank-game-card" data-rank-game="${g.id}"><img src="${A(g.art)}" alt=""><div><strong>${g.name}</strong><small>${g.players} người chơi</small></div><span class="rank-game-crown">♛ #${i+1}</span><span class="rank-game-view">Xem chi tiết ›</span></button>`).join('')}</div>`}
function leaderboard(){return `<div class="rank-page">${rankTop('Bảng xếp hạng','Khám phá những người chơi xuất sắc nhất<br>trong cộng đồng WiiG')}${rankTabs('rankCategory',[['game','Trò chơi','game'],['tournament','Giải đấu','trophy']])}${rankTabs('rankPeriod',[['week','Trong tuần'],['month','Trong tháng'],['quarter','Trong quý']])}<div class="rank-section-top"><strong>👑 Top người chơi tuần</strong><small>${rankSvg('clock')} Cập nhật lúc 12/10/2026 21:00</small></div>${rankPodium()}${rankBoardRows(5)}<button class="rank-outline-btn" data-rank-go="rankGame">Xem bảng xếp hạng trò chơi ${rankSvg('chevron')}</button><div class="rank-subtitle"><h3>Bảng xếp hạng theo trò chơi</h3><button data-rank-go="rankGame">Xem tất cả ${rankSvg('chevron')}</button></div>${rankGameCards()}<button class="rank-tournament-card" data-rank-go="rankTournament"><span class="rank-tournament-symbol">${rankSvg('trophy')}</span><span><strong>Bảng xếp hạng giải đấu</strong><small>Xem những người chơi xuất sắc nhất tại các giải đấu</small></span>${rankSvg('chevron')}</button></div>`}
function rankGame(){const g=rankGames.find(g=>g.id===state.rankGame)||rankGames[0];return `<div class="rank-page">${rankTop('Xếp hạng '+g.name,'',true)}<div class="rank-selectors"><label><img src="${A(g.art)}" alt=""><select id="rank-game-select">${rankGames.map(x=>`<option value="${x.id}" ${g.id===x.id?'selected':''}>${x.name}</option>`).join('')}</select></label><label>${rankSvg('location')}<select id="rank-region-select"><option>Việt Nam</option><option>Toàn cầu</option><option>Thái Lan</option></select></label></div>${rankTabs('rankPeriod',[['week','Tuần này'],['month','Tháng này'],['quarter','Quý này']])}<div class="rank-dates">${rankSvg('calendar')} Thời gian: 06/10/2026 - 12/10/2026 <span>♕ Xếp hạng theo tổng điểm</span></div>${rankPodium()}${rankBoardRows(8,'detail')}<button class="rank-outline-btn" data-rank-more>Xem thêm bảng xếp hạng ⌄</button></div>`}
function rankTournament(){return `<div class="rank-page">${rankTop('Speed Challenge','Bảng xếp hạng giải đấu',true)}<div class="rank-challenge"><img src="${A('rank-space')}" alt=""><div><span class="rank-live">● ĐANG DIỄN RA</span><h2>Jigsaw Puzzle<br>Speed Challenge</h2><p>Thử thách tốc độ, chinh phục điểm số cao nhất!</p></div><div class="rank-countdown">${rankSvg('clock')} Kết thúc sau<br><strong>2 ngày 12:30:45</strong></div></div><div class="rank-dates">${rankSvg('calendar')} Tuần này · 06/10 - 12/10/2026</div><div class="rank-podium"><img src="${A('rank-podium-plain')}" alt="Ba người chơi dẫn đầu Speed Challenge"></div>${rankBoardRows(7,'tournament')}<div class="rank-my-position">${rankSvg('chart')}<span>Hạng của bạn: <strong>#8</strong><small>High Score: 4,900 điểm</small></span><button data-rank-go="rankHistory">Tăng 2 hạng ›</button></div><button class="rank-main-btn" data-action="join">${rankSvg('game')} ${state.joined?'Thi đấu tiếp':'Tham gia giải đấu'} ${rankSvg('chevron')}</button></div>`}
function rankHistory(){const type=state.rankHistoryCategory||'game';return `<div class="rank-page">${rankTop('Lịch sử xếp hạng','Xem kết quả các kỳ xếp hạng đã kết thúc',true,false)}${rankTabs('rankHistoryCategory',[['game','Trò chơi','game'],['tournament','Giải đấu','trophy']])}${rankTabs('rankPeriod',[['week','Tuần'],['month','Tháng'],['quarter','Quý']])}<div class="rank-history-list">${rankGames.map((g,i)=>`<article class="rank-history-card"><div class="rank-history-card-head"><img src="${A(g.art)}" alt=""><div><strong>${type==='tournament'?g.name+' Challenge':g.name}</strong><small>Tuần ${['06/10/2026 - 12/10/2026','29/09/2026 - 05/10/2026'][i%2]}</small></div><span class="rank-done">${rankSvg('check')} Đã chốt</span><button data-rank-game="${g.id}" aria-label="Xem bảng xếp hạng">${rankSvg('chevron')}</button></div><div class="rank-history-stats"><div>${rankSvg('star')}<span>Điểm của bạn<strong>${rankNumber(g.score)}</strong></span></div><div>${rankSvg('chart')}<span>Hạng của bạn<strong>#${g.place}</strong></span></div><button data-rank-game="${g.id}">Xem bảng ›</button></div></article>`).join('')}</div></div>`}
const purchaseOptions=[{count:10,price:25000,art:'pkg10',tag:'',desc:'Trải nghiệm game mỗi ngày'},{count:20,price:45000,art:'pkg20',tag:'',desc:'Thêm lượt chơi hấp dẫn'},{count:50,price:99000,art:'pkg50',tag:'Phổ biến nhất',desc:'Chơi thỏa thích hơn'}];
const money=n=>n.toLocaleString('vi-VN')+'đ';
function purchaseSelected(){return purchaseOptions.find(p=>p.count===Number(state.selectedPackage))||purchaseOptions[1]}
function purchaseHeader(title,subtitle=''){return `<div class="purchase-header"><button class="purchase-back" data-back aria-label="Quay lại">‹</button><div><h1>${title}</h1>${subtitle?`<p>${subtitle}</p>`:''}</div></div>`}
function purchaseHighlights(){return `<div class="purchase-highlights"><span><b>∞</b> Không hết hạn</span><span><b>♧</b> Cộng dồn</span><span><b>♢</b> An toàn</span></div>`}
function packages(){return `<div class="purchase-page purchase-listing-v27">
<section class="pkg-intro"><div class="pkg-intro-copy"><h1>Gói lượt chơi</h1><p>Mua thêm lượt chơi để khám phá<br>thế giới game hấp dẫn trên WiiG.</p></div><img class="pkg-boy" src="${A('package-boy')}" alt="Nhân vật WiiG cầm tay chơi game"></section>
<div class="pkg-benefits-row"><div><span class="pkg-benefit-icon mint">∞</span><span>Không<br>hết hạn</span></div><div><span class="pkg-benefit-icon violet">▱</span><span>Cộng dồn<br>lượt chơi</span></div><div><span class="pkg-benefit-icon blue">⟳</span><span>Gia hạn<br>tự động</span></div></div>
<div class="pkg-offer-list">${purchaseOptions.map((p,i)=>`<article class="pkg-offer ${i===0?'featured':''}">
${i===0?'<span class="pkg-featured-badge">Phù hợp trải nghiệm</span>':''}
<img class="pkg-offer-art" src="${A(p.art)}" alt="Minh họa gói ${p.count} lượt">
<div class="pkg-offer-copy"><h2>Gói <span>${p.count}</span> lượt</h2><p>${i===0?'Phù hợp để trải nghiệm<br>các game yêu thích':i===1?'Lựa chọn phổ biến cho<br>người chơi thường xuyên':'Chơi thỏa thích mọi đam mê<br>không lo hết lượt'}</p>
<div class="pkg-offer-perks"><span><b>∞</b> Không<br>hết hạn</span><span><b>▱</b> Cộng dồn<br>lượt chơi</span><span><b>⟳</b> Gia hạn<br>tự động</span></div></div>
<div class="pkg-offer-bottom"><div class="pkg-price">${money(p.price)} <small>/ ${p.count} lượt</small></div><button class="${i===0?'pkg-buy':'pkg-view'}" data-select-package="${p.count}">${i===0?'Đăng ký gói':'Xem chi tiết'} →</button></div>
</article>`).join('')}</div>
</div>`}
function pdSvg(name){const paths={
infinity:'<path d="M6.3 8.2C3.8 8.2 2 10 2 12s1.8 3.8 4.3 3.8c2.4 0 3.7-2.1 5.7-3.8 2-1.7 3.3-3.8 5.7-3.8 2.5 0 4.3 1.8 4.3 3.8s-1.8 3.8-4.3 3.8c-2.4 0-3.7-2.1-5.7-3.8-2-1.7-3.3-3.8-5.7-3.8Z"/>',
stack:'<rect x="5" y="3" width="14" height="5" rx="1.5"/><rect x="5" y="10" width="14" height="5" rx="1.5"/><rect x="5" y="17" width="14" height="4" rx="1.5"/>',
refresh:'<path d="M20.5 8.5A8.5 8.5 0 1 0 21 13"/><path d="M20.5 3.5v5h-5"/>',
phone:'<rect x="7" y="2" width="10" height="20" rx="2.5"/><path d="M11 18h2"/>',
signal:'<path d="M4 17v-3m5 3V9m5 8V5m5 12V3"/>',
manage:'<rect x="5" y="3" width="14" height="18" rx="2"/><path d="M9 8h6M9 12h6M9 16h4"/>',
check:'<path d="m5 12 4 4L19 6"/>'
};return `<svg class="pd-svg pd-svg-${name}" viewBox="0 0 24 24" width="22" height="22" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.check}</svg>`}
function packageDetail(){const p=purchaseSelected();return `<div class="purchase-page pkg-detail-v29">
<section class="pd-hero"><div class="pd-hero-copy"><h1>Gói <span>${p.count}</span> lượt</h1><p>Lựa chọn phổ biến cho<br>người chơi thường xuyên</p><div class="pd-hero-perks"><span>${pdSvg('infinity')} Lượt không hết hạn</span><span>${pdSvg('stack')} Được cộng dồn lượt</span><span>${pdSvg('refresh')} Tự động gia hạn</span></div></div><img src="${A(p.art)}" alt="Gói ${p.count} lượt"></section>
<div class="pd-stats"><div><div class="pd-stat-icon">${pdSvg("stack")}</div><div><small>Lượt nhận</small><strong>${p.count} lượt</strong><p>Cộng thêm vào tài khoản sau khi đăng ký thành công</p></div></div><div><div class="pd-stat-icon">${pdSvg("phone")}</div><div><small>Phương thức thanh toán</small><strong>Trừ cước qua nhà mạng</strong><p>Thanh toán bằng tài khoản điện thoại theo gói nhà mạng của bạn</p></div></div></div>
<div class="pd-feature pd-mint"><span class="pd-icon">${pdSvg("infinity")}</span><div><strong>Lượt không hết hạn và được cộng dồn</strong><p>Các lượt chơi sẽ được cộng dồn vào tài khoản và không bị hết hạn.</p></div></div>
<div class="pd-feature"><span class="pd-icon">${pdSvg("refresh")}</span><div><strong>Tự động gia hạn</strong><p>Gói sẽ tự động gia hạn theo chu kỳ của nhà mạng. Bạn có thể hủy gia hạn bất cứ lúc nào.</p></div></div>
<button class="pd-feature pd-link" data-go="helpCenter"><span class="pd-icon">${pdSvg("manage")}</span><div><strong>Quản lý và hủy gia hạn</strong><p>Bạn có thể hủy gia hạn bất cứ lúc nào bằng cách truy cập thông tin gói trong tài khoản.</p></div><span class="pd-arrow">Xem hướng dẫn ›</span></button>
<div class="pd-summary"><div><small>Giá gói</small><strong class="pd-price">Theo gói<br>nhà mạng</strong><p>Giá được hiển thị khi đăng ký</p></div><div><small>Bạn sẽ nhận</small><ul><li>${pdSvg('stack')}${p.count} lượt chơi</li><li>${pdSvg('infinity')}Không hết hạn</li><li>${pdSvg('stack')}Được cộng dồn</li><li>${pdSvg('refresh')}Tự động gia hạn</li></ul></div></div>
<label class="pd-terms"><input type="checkbox" id="package-terms" ${state.packageTermsAccepted?'checked':''}><span>Tôi đã đọc và đồng ý với <a href="#" data-go="termsPrivacy">Điều khoản sử dụng</a> và <a href="#" data-go="termsPrivacy">Chính sách bảo mật</a> của WiiG.</span></label>
<button class="btn purple block pd-continue" data-action="continuePackage" ${state.packageTermsAccepted?'':'disabled'}>Tiếp tục →</button>
</div>`}
function packageConfirm(){const p=purchaseSelected();const phone=state.phone?`+84 ${esc(state.phone.replace(/^0/,''))}`:'+84 8xx xxx xxx';return `<div class="purchase-page pkg-confirm-v31">
${purchaseHeader('Xác nhận đăng ký')}
<section class="pc-hero"><img src="${A(p.art)}" alt="Gói ${p.count} lượt"><div class="pc-hero-copy"><small>Gói lượt chơi</small><h2>Gói <em>${p.count}</em> lượt</h2><p>Lựa chọn phổ biến cho<br>người chơi thường xuyên</p><div class="pc-hero-perks"><span>${pdSvg('infinity')} Không<br>hết hạn</span><span>${pdSvg('stack')} Cộng dồn<br>lượt chơi</span><span>${pdSvg('refresh')} Tự động<br>gia hạn</span></div></div></section>
<section class="pc-section"><h3>Thông tin đăng ký</h3><div class="pc-list">
<div class="pc-info-row"><span class="pc-icon purple">${pdSvg('phone')}</span><div><small>Số điện thoại</small><strong>${phone}</strong></div><button class="pc-change" data-action="changePurchasePhone">Thay đổi</button></div>
<div class="pc-info-row"><span class="pc-icon mint">${pdSvg('signal')}</span><div><small>Nhà mạng</small><strong>Viettel</strong></div></div>
<div class="pc-info-row"><span class="pc-icon purple">${pdSvg('phone')}</span><div><small>Phương thức thanh toán</small><strong>Tài khoản điện thoại</strong><p>Trừ cước qua nhà mạng của bạn</p></div></div>
</div></section>
<section class="pc-section"><h3>Chi tiết gói</h3><div class="pc-list">
<div class="pc-info-row"><span class="pc-icon purple">${pdSvg('stack')}</span><div><small>Số lượt nhận</small><strong>${p.count} lượt</strong></div></div>
<div class="pc-info-row"><span class="pc-icon mint">${pdSvg('manage')}</span><div><small>Giá gói</small><strong>Theo gói nhà mạng</strong><p>Giá được hiển thị khi đăng ký</p></div></div>
<div class="pc-info-row"><span class="pc-icon blue">${pdSvg('refresh')}</span><div><small>Gia hạn tự động</small><p>Gói sẽ tự động gia hạn theo chu kỳ của nhà mạng.<br>Bạn có thể hủy gia hạn bất cứ lúc nào.</p></div></div>
</div></section>
<button class="pc-guidance" data-go="helpCenter"><span class="pc-icon purple">${pdSvg('manage')}</span><span>Bạn có thể hủy gia hạn bất cứ lúc nào bằng cách xem thông tin gói trong tài khoản.</span><b>Xem hướng dẫn ›</b></button>
<label class="pc-terms"><input type="checkbox" id="confirm-terms" ${state.confirmTermsAccepted?'checked':''}><span>Tôi đã đọc và đồng ý với <a href="#" data-go="termsPrivacy">Điều khoản sử dụng</a> và <a href="#" data-go="termsPrivacy">Chính sách bảo mật</a> của WiiG.</span></label>
<button class="btn purple block pc-submit" data-action="confirmPurchase" ${state.confirmTermsAccepted?'':'disabled'}>Xác nhận thanh toán →</button><button class="pc-cancel" data-back>Quay lại</button>
<p class="pc-demo-note">Đây là bản demo, không phát sinh cước điện thoại thực tế.</p>
</div>`}
function purchaseLogo(){return `<div class="purchase-brand"><img src="${A('wiig-logo')}" alt="WiiG"></div>`}
function paymentDetails(p,success=false){const date=state.paymentDate||new Date().toLocaleString('vi-VN');return `<section class="pay-details"><div class="pay-row"><span class="pay-icon violet">${pdSvg('stack')}</span><div><small>Gói đăng ký</small><strong>Gói ${p.count} lượt</strong></div></div><div class="pay-row"><span class="pay-icon mint">${pdSvg('phone')}</span><div><small>Nhà mạng</small><strong>Viettel</strong></div></div><div class="pay-row"><span class="pay-icon violet">${pdSvg('phone')}</span><div><small>Phương thức thanh toán</small><strong>Tài khoản điện thoại</strong><p>Trừ cước qua nhà mạng của bạn</p></div></div>${success?`<div class="pay-row"><span class="pay-icon blue">${pdSvg('manage')}</span><div><small>Mã giao dịch</small><strong>${state.paymentCode||'TX-DEMO'}</strong></div></div>`:''}<div class="pay-row"><span class="pay-icon blue">${pdSvg('manage')}</span><div><small>${success?'Thời gian':'Mã giao dịch'}</small><strong>${success?date:(state.paymentCode||'TX-DEMO')}</strong></div></div></section>`}
function packageProcessing(){const p=purchaseSelected();return `<div class="purchase-page payment-flow-v32">${purchaseLogo()}<div class="pay-art"><img src="${A('pkgprocessing')}" alt="Robot WiiG đang xác nhận"></div><h1>Đang xác nhận<br>với nhà mạng</h1><p class="pay-subtitle">Vui lòng kiểm tra kết quả sau ít phút.<br>Chúng tôi sẽ thông báo ngay khi hoàn tất.</p>${paymentDetails(p)}<div class="pay-warning"><span>${pdSvg('manage')}</span><div><strong>Không đóng trang khi đang xử lý</strong><p>Quá trình xác nhận có thể mất vài phút tùy theo nhà mạng. Bạn sẽ nhận thông báo ngay khi hoàn tất.</p></div></div><button class="pay-home-outline" data-go="home">Về trang chủ ${pdSvg('manage')}</button><div class="pay-demo-control"><button class="btn purple block" data-action="completePurchase">Mô phỏng thanh toán thành công →</button><small>Chỉ dùng trong bản demo, không trừ tiền thật.</small></div></div>`}
function packageSuccess(){const p=purchaseSelected();return `<div class="purchase-page payment-flow-v32 pay-success">${purchaseLogo()}<div class="pay-art success-art"><img src="${A('pkgsuccess')}" alt="Robot WiiG chúc mừng đăng ký thành công"></div><h1>Đăng ký thành công</h1><p class="pay-subtitle">Bạn đã đăng ký thành công gói ${p.count} lượt chơi.<br>Lượt chơi đã được cộng vào tài khoản.</p><div class="pay-success-banner"><span class="pay-icon violet">${pdSvg('stack')}</span><div><small>Số lượt nhận thêm</small><strong>+${p.count} <em>lượt</em></strong></div></div><section class="pay-details"><div class="pay-row"><span class="pay-icon violet">${pdSvg('stack')}</span><div><small>Số dư hiện tại</small><strong>${state.credits} lượt</strong></div></div><div class="pay-row"><span class="pay-icon blue">${pdSvg('stack')}</span><div><small>Gói đã đăng ký</small><strong>Gói ${p.count} lượt</strong><p>Lựa chọn phổ biến cho người chơi thường xuyên</p></div></div><div class="pay-row"><span class="pay-icon mint">${pdSvg('phone')}</span><div><small>Nhà mạng</small><strong>Viettel</strong></div></div><div class="pay-row"><span class="pay-icon violet">${pdSvg('manage')}</span><div><small>Mã giao dịch</small><strong>${state.paymentCode||'TX-DEMO'}</strong></div><div class="pay-date">${state.paymentDate||''}</div></div></section><button class="btn purple block pay-primary" data-go="wallet">Xem ví lượt →</button><button class="pay-home-outline" data-go="home">${FOOTER_ICONS['nav-home']} Về trang chủ</button><div class="pay-help"><span>${pdSvg('manage')}</span><p>Nếu bạn cần hỗ trợ, vui lòng liên hệ Trung tâm hỗ trợ. Chúng tôi luôn sẵn sàng giúp bạn.</p><span>›</span></div></div>`}
function wIcon(name){const p={
coins:'<rect x="4" y="4" width="16" height="5" rx="2"/><path d="M4 8v4c0 2 16 2 16 0V8M4 12v4c0 2 16 2 16 0v-4"/>',
game:'<path d="M6.9 6h10.2a4 4 0 0 1 3.9 3.2l1 5.3a3 3 0 0 1-4.8 3l-2.8-2.2H9.6l-2.8 2.2a3 3 0 0 1-4.8-3l1-5.3A4 4 0 0 1 6.9 6Z"/><path d="M7 9v5M4.5 11.5h5"/><circle cx="16.5" cy="10" r=".8" fill="currentColor"/><circle cx="18.5" cy="12" r=".8" fill="currentColor"/>',
clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2M4 4l-2 2"/>',
plus:'<circle cx="12" cy="12" r="9"/><path d="M12 7v10M7 12h10"/>',
info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v5M12 8h.01"/>',
chevron:'<path d="m9 5 7 7-7 7"/>',
history:'<path d="M3 11a9 9 0 1 1 2 6M3 4v7h7M12 7v5l4 2"/>',
infinity:'<path d="M6.5 8.5C4 8.5 2 10 2 12s2 3.5 4.5 3.5C9 15.5 10 13 12 12c2-1 3-3.5 5.5-3.5S22 10 22 12s-2 3.5-4.5 3.5C15 15.5 14 13 12 12c-2-1-3-3.5-5.5-3.5Z"/>'
};return `<svg viewBox="0 0 24 24" width="21" height="21" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${p[name]||p.info}</svg>`}
function walletTransactions(){const entries=state.transactions.map((t,i)=>({type:'purchase',title:'Mua gói '+t.credits+' lượt',date:t.date||'',delta:Number(t.credits),id:i}));const spends=(state.walletSpends||[]).map((t,i)=>({type:'play',title:'Chơi game · '+(t.name||'WiiG'),date:t.date||'',delta:-Number(t.credits||1),id:i}));return [...entries,...spends].sort((a,b)=>b.id-a.id)}
function walletActivity(limit=5){const entries=walletTransactions().slice(0,limit);return entries.length?entries.map(t=>`<div class="wallet-entry"><span class="wallet-entry-icon ${t.type}">${wIcon(t.type==='purchase'?'coins':'game')}</span><div class="wallet-entry-info"><strong>${t.title}</strong><small>${t.date}</small></div><div class="wallet-entry-amount ${t.delta>0?'positive':'negative'}"><strong>${t.delta>0?'+':''}${t.delta} lượt</strong><small>${t.type==='purchase'?'Đã cộng vào ví':'Đã sử dụng'}</small></div></div>`).join(''):`<div class="wallet-empty">Chưa có biến động lượt chơi. Các lượt mua và sử dụng sẽ xuất hiện tại đây.</div>`}
function wallet(){return `<div class="wallet-page-v33"><div class="wallet-top"><button class="wallet-logo-link" data-go="home" aria-label="Về trang chủ"><img src="${A('wiig-logo')}" alt="WiiG"></button><button class="wallet-history-pill" data-go="walletHistory">${wIcon('history')} Lịch sử ${wIcon('chevron')}</button></div><div class="wallet-intro"><h1>Ví lượt chơi</h1><p>Quản lý số dư và theo dõi<br>lịch sử biến động lượt chơi.</p></div><div class="wallet-balance"><div class="wallet-balance-copy"><small>Số dư hiện tại</small><h2>${state.credits} lượt</h2><span>${wIcon('infinity')} Không hết hạn</span></div><img src="${A('wallet-figure')}" alt="Ví xu game WiiG"></div><div class="wallet-quick-actions"><button class="wallet-action-buy" data-go="packages"><span class="wallet-action-symbol">${wIcon('plus')}</span><span><strong>Mua thêm lượt</strong><small>Chọn gói phù hợp<br>với nhu cầu</small></span>${wIcon('chevron')}</button><button class="wallet-action-history" data-go="walletHistory"><span class="wallet-action-symbol">${wIcon('clock')}</span><span><strong>Lịch sử biến động</strong><small>Xem chi tiết<br>các lượt đã nhận và sử dụng</small></span>${wIcon('chevron')}</button></div><div class="wallet-activity-title"><h3>Biến động gần đây</h3><button data-go="walletHistory">Xem tất cả ${wIcon('chevron')}</button></div><div class="wallet-activity">${walletActivity(5)}</div><div class="wallet-info"><span>${wIcon('info')}</span><div><strong>Lượt chơi không hết hạn và được cộng dồn</strong><p>Tất cả lượt chơi bạn nhận được đều được cộng dồn vào tài khoản và có thể sử dụng bất cứ lúc nào.</p></div></div></div>`}
function walletHistory(){return `<div class="wallet-page-v33"><div class="wallet-history-heading"><button data-back aria-label="Quay lại">‹</button><h1>Lịch sử biến động</h1></div><div class="wallet-history-summary">${wIcon('coins')} Số dư hiện tại: <b>${state.credits} lượt</b></div><div class="wallet-history-filters">${[['all','Tất cả'],['purchase','Đã nhận'],['play','Đã sử dụng']].map(([v,t])=>`<button data-wallet-filter="${v}" class="${(state.walletFilter||'all')===v?'selected':''}">${t}</button>`).join('')}</div><div class="wallet-activity">${(state.walletFilter||'all')==='all'?walletActivity(999):(()=>{const rows=walletTransactions().filter(t=>t.type===state.walletFilter);return rows.length?rows.map(t=>`<div class="wallet-entry"><span class="wallet-entry-icon ${t.type}">${wIcon(t.type==='purchase'?'coins':'game')}</span><div class="wallet-entry-info"><strong>${t.title}</strong><small>${t.date}</small></div><div class="wallet-entry-amount ${t.delta>0?'positive':'negative'}"><strong>${t.delta>0?'+':''}${t.delta} lượt</strong></div></div>`).join(''):'<div class="wallet-empty">Chưa có giao dịch trong mục này.</div>'})()}</div><button class="wallet-return" data-back>‹ Quay lại</button></div>`}
function account(){if(!state.loggedIn)return auth();return `<div class="profile-page profile-figma-v40">
<div class="profile-top"><img class="profile-logo" src="${A('wiig-logo')}" alt="WiiG"><div class="profile-top-actions"><button data-go="notifications" aria-label="Thông báo"><img src="${A('account-bell-figma')}" alt=""><img class="profile-notice-dot" src="${A('account-notice-dot')}" alt=""></button><button data-go="termsPrivacy" aria-label="Cài đặt"><img src="${A('account-settings-figma')}" alt=""></button></div></div>
<div class="profile-intro"><div><h1>Tài khoản của tôi</h1><p>Quản lý thông tin và trải nghiệm của bạn trên WiiG.</p><div class="profile-user"><img src="${A('account-avatar-figma')}" alt="Ảnh đại diện"><div><strong>Người chơi WiiG</strong><small>+84 ${esc(state.phone||'—')} · <span>Đã xác thực</span></small><em>♕ Thành viên cơ bản</em></div></div></div><img class="profile-mascot" src="${A('account-mascot')}" alt="Robot WiiG"></div>
<div class="profile-balance"><div class="profile-balance-left"><img src="${A('coin-icon')}" alt=""><div><small>Số dư lượt chơi</small><strong>${state.credits} lượt</strong></div></div><button class="btn purple" data-go="packages">Nạp thêm lượt →</button></div>
<div class="profile-menu">
<button data-action="editprofile"><img class="profile-menu-asset" src="${A('account-profile-figma')}" alt=""><span><strong>Thông tin cá nhân</strong><small>Xem và cập nhật thông tin tài khoản</small></span><b>›</b></button>
<button data-go="mygames"><img class="profile-menu-asset" src="${A('account-games-figma')}" alt=""><span><strong>Lịch sử chơi</strong><small>Xem lịch sử các game đã chơi</small></span><b>›</b></button>
<button data-go="walletHistory"><img class="profile-menu-asset" src="${A('account-transactions-figma')}" alt=""><span><strong>Giao dịch</strong><small>Lịch sử nạp gói và sử dụng lượt chơi</small></span><b>›</b></button>
</div><div class="profile-menu">
<button data-action="language"><img class="profile-menu-asset" src="${A('account-language-figma')}" alt=""><span><strong>Ngôn ngữ</strong><small></small></span><em>Tiếng Việt</em><b>›</b></button>
<button data-go="helpCenter"><img class="profile-menu-asset" src="${A('account-help-figma')}" alt=""><span><strong>Hỗ trợ</strong><small>Trung tâm trợ giúp và liên hệ</small></span><b>›</b></button>
<button data-go="termsPrivacy"><img class="profile-menu-asset" src="${A('account-privacy-figma')}" alt=""><span><strong>Điều khoản & Quyền riêng tư</strong><small>Xem điều khoản sử dụng dịch vụ</small></span><b>›</b></button>
</div><button class="profile-logout" data-action="logout"><img src="${A('account-logout-figma')}" alt=""> <span>Đăng xuất</span><b>›</b></button>
</div>`}

/* P29–P33: Notifications, notification detail, SMS cancellation, terms, help. */
const noticeData=[
{id:1,type:'system',icon:'gift',title:'Gói của bạn gần thanh toán',description:'Bạn đã gia hạn gói WiiG. Thông tin nhận thêm 120 lượt chơi.',age:'5 phút trước',unread:true},
{id:2,type:'tournament',icon:'trophy',title:'Tournament đã kết thúc',description:'Giải Speed Challenge đã kết thúc. Bạn đạt hạng #3 với 4.900 điểm.',age:'1 giờ trước',unread:true},
{id:3,type:'game',icon:'game',title:'Kết quả lượt chơi',description:'Bạn đạt 5.450 điểm trong Jigsaw Puzzle. Xem chi tiết kết quả ngay!',age:'3 giờ trước',unread:true},
{id:4,type:'reward',icon:'gift',title:'Phần thưởng đã sẵn sàng',description:'Bạn nhận được phần thưởng thành tích từ sự kiện hàng tuần.',age:'1 ngày trước',unread:false},
{id:5,type:'system',icon:'info',title:'Cập nhật sự kiện mới',description:'Chào đón mùa giải mới cùng WiiG. Tham gia ngay!',age:'2 ngày trước',unread:false},
{id:6,type:'tournament',icon:'trophy',title:'Nhắc nhở giải đấu',description:'Giải Blue Train Battle sắp bắt đầu sau 1 ngày.',age:'3 ngày trước',unread:false},
{id:7,type:'game',icon:'star',title:'Bạn đã thăng hạng!',description:'Bạn đã tăng 5 bậc trong bảng xếp hạng tuần này.',age:'4 ngày trước',unread:false},
{id:8,type:'system',icon:'info',title:'Thông báo hệ thống',description:'Chúng tôi đã cập nhật Điều khoản sử dụng phiên bản mới.',age:'5 ngày trước',unread:false}];
function noticeIcon(k){return `<span class="notice-icon notice-icon-${k}">${k==='trophy'?'🏆':k==='gift'?'🎁':k==='game'?'🎮':k==='star'?'★':k==='info'?'ⓘ':'🔔'}</span>`}
function supportHead(title,sub=''){return `<div class="support-head"><button data-support-back aria-label="Quay lại">‹</button><div><h1>${title}</h1>${sub?`<p>${sub}</p>`:''}</div></div>`}
function notifications(){let tab=state.noticeTab||'all';let read=state.noticeRead||[];let items=noticeData.filter(n=>tab==='all'||(tab==='unread'&&!read.includes(n.id)&&n.unread));return `<div class="support-page notifications-page">${supportHead('Thông báo',`${noticeData.filter(n=>n.unread&&!read.includes(n.id)).length} thông báo chưa đọc`)}<div class="notice-mark"><button data-notice-readall>✓ Đánh dấu đã đọc tất cả</button></div><div class="support-tabs"><button data-notice-tab="all" class="${tab==='all'?'selected':''}">Tất cả (${noticeData.length})</button><button data-notice-tab="unread" class="${tab==='unread'?'selected':''}">Chưa đọc (${noticeData.filter(n=>n.unread&&!read.includes(n.id)).length})</button></div><div class="notice-list">${items.map(n=>`<button class="notice-row ${n.unread&&!read.includes(n.id)?'unread':''}" data-notice-id="${n.id}">${noticeIcon(n.icon)}<span class="notice-row-copy"><strong>${n.title}</strong><small>${n.description}</small></span><span class="notice-time">${n.unread&&!read.includes(n.id)?'<i></i>':''}${n.age}<b>›</b></span></button>`).join('')||`<div class="notice-empty"><img src="${A('notice-empty')}" alt="Robot WiiG"><h3>Không có thông báo mới</h3><p>Chúng tôi sẽ thông báo cho bạn khi có tin mới.</p></div>`}</div><div class="notice-empty-foot"><img src="${A('notice-empty')}" alt=""><div><strong>Không có thông báo mới?</strong><small>Chúng tôi sẽ thông báo cho bạn khi có tin mới.</small></div></div></div>`}
function notificationDetail(){const n=noticeData.find(x=>x.id===state.noticeId)||noticeData[1];return `<div class="support-page">${supportHead('Chi tiết thông báo','Xem nội dung thông báo của hệ thống')}<div class="notice-detail-hero"><div class="notice-detail-top"><span>🏆 ${n.type==='tournament'?'Giải đấu':'WiiG Portal'}</span><small>12/10/2026 · 10:24</small></div><div class="notice-detail-body"><div><h2>${n.type==='tournament'?'Kết quả Tournament':n.title}</h2><h3>${n.type==='tournament'?'Speed Challenge':''}</h3><p>${n.description}</p></div><img src="${A('notice-trophy')}" alt="Cúp chiến thắng WiiG"></div><div class="notice-results"><div>🏅 <small>Bạn đạt hạng</small><strong>#3</strong></div><div>🏆 <small>Điểm cao nhất</small><strong>12.450</strong></div></div></div><section class="support-panel"><h3>▤ Thông tin chi tiết</h3>${[['Tên giải đấu','Speed Challenge'],['Thời gian diễn ra','05/10/2026 – 12/10/2026'],['Số người tham gia','12.580 người chơi'],['Thứ hạng của bạn','#3'],['Điểm cao nhất','12.450 điểm'],['Thời điểm đạt điểm','12/10/2026 · 09:18']].map(([a,b])=>`<div class="support-kv"><span>${a}</span><b>${b}</b></div>`).join('')}</section><div class="support-note"><strong>🏆 Nhà mạng sẽ trao thưởng</strong><p>Giải thưởng (nếu có) sẽ được nhà mạng phụ trách trao theo thể lệ của chương trình.</p></div><div class="support-note violet"><strong>ⓘ Lưu ý</strong><p>Kết quả xếp hạng được tính theo điểm cao nhất và thời điểm đạt điểm trong kỳ.</p></div><button class="support-primary" data-go="rankTournament">▥ Xem kết quả giải ›</button></div>`}
function smsGuide(){const steps=[['1','Bước 1: Mở tin nhắn','Mở ứng dụng Tin nhắn (SMS) trên điện thoại của bạn.','sms-open-art'],['2','Bước 2: Soạn cú pháp','Soạn tin nhắn theo cú pháp do nhà mạng cung cấp.','sms-syntax-art'],['3','Bước 3: Gửi SMS','Gửi tin nhắn đến đầu số do nhà mạng cung cấp.','sms-send-art']];return `<div class="support-page sms-figma-v38">${supportHead('Hướng dẫn hủy gói','Hủy gia hạn để không bị tự động gia hạn ở chu kỳ tiếp theo')}<div class="support-hero sms-hero"><div><h2>Hủy gia hạn<br>qua SMS</h2><p>Thực hiện theo hướng dẫn dưới đây để theo dõi gói nhà mạng của bạn.</p></div><img src="${A('sms-banner-art')}" alt="Nhân vật hướng dẫn hủy gia hạn SMS"></div><h3>Thực hiện theo các bước</h3><div class="sms-timeline">${steps.map(([i,t,x,art])=>`<div class="sms-step-figma"><span class="sms-number">${i}</span><div class="sms-step-copy"><strong>${t}</strong><p>${x}</p></div><img src="${A(art)}" alt="Minh họa ${t}"></div>`).join('')}</div><div class="support-note"><strong>ⓘ Cú pháp theo nhà mạng</strong><p>Mỗi nhà mạng có cú pháp và đầu số khác nhau. Vui lòng soạn tin nhắn theo đúng thông tin được cung cấp.</p></div><div class="support-panel"><div class="support-kv"><span>Cú pháp hủy gia hạn</span><b>[CÚ PHÁP NHÀ MẠNG]</b></div><div class="support-kv"><span>Đầu số gửi tin nhắn</span><b>[ĐẦU SỐ]</b></div><button class="support-primary" data-copy-sms>▣ Sao chép cú pháp</button></div><div class="support-note warm"><strong>⚠ Lưu ý quan trọng</strong><p>Lệnh hủy chỉ có hiệu lực theo quy định của nhà mạng. Không sử dụng cú pháp mẫu khi chưa xác nhận với nhà mạng.</p></div><button class="support-secondary" data-support-back>‹ Trở về</button></div>`}
function termsPrivacy(){const privacy=state.legalTab==='privacy';const sections=privacy?[
['Thu thập thông tin','WiiG sử dụng thông tin được cung cấp để vận hành tài khoản và hỗ trợ dịch vụ.'],
['Sử dụng dữ liệu','Thông tin được sử dụng cho các chức năng đăng nhập, trò chơi và lịch sử giao dịch.'],
['Bảo mật thông tin','Dữ liệu cá nhân cần được bảo vệ và chỉ xử lý theo chính sách áp dụng.'],
['Quyền của người dùng','Người dùng có thể liên hệ bộ phận hỗ trợ về thông tin tài khoản.']
]:[
['Tổng quan','Điều khoản này quy định việc sử dụng dịch vụ game và nội dung trên WiiG.'],
['Tài khoản và bảo mật','Bạn có trách nhiệm bảo vệ thông tin đăng nhập và sử dụng tài khoản hợp lệ.'],
['Gói dịch vụ và thanh toán','Giá và quyền lợi của gói được hiển thị trước khi đăng ký.'],
['Sử dụng dịch vụ','Vui lòng tuân thủ quy định cộng đồng và điều kiện sử dụng.'],
['Quyền và trách nhiệm của WiiG','WiiG có thể điều chỉnh dịch vụ theo các điều khoản công bố.']
];const toc=['Tổng quan','Tài khoản và bảo mật','Gói dịch vụ và thanh toán','Sử dụng dịch vụ','Quyền và trách nhiệm','Nội dung và sở hữu trí tuệ','Giới hạn trách nhiệm','Thay đổi điều khoản','Liên hệ'];return `<div class="support-page legal-figma-v39">${supportHead('Điều khoản & Quyền riêng tư','Vui lòng đọc kỹ các điều khoản và chính sách của WiiG')}<div class="support-tabs"><button data-legal-tab="terms" class="${!privacy?'selected':''}">Điều khoản sử dụng</button><button data-legal-tab="privacy" class="${privacy?'selected':''}">Chính sách quyền riêng tư</button></div><div class="legal-hero"><div><h2>${privacy?'Chính sách quyền riêng tư':'Điều khoản sử dụng'}</h2><p>${privacy?'Cách WiiG xử lý và bảo vệ thông tin người dùng.':'Quy định về việc sử dụng nền tảng, dịch vụ và nội dung trên WiiG.'}</p></div><img src="${A('legal-shield')}" alt="Tài liệu và lá chắn bảo mật"></div><div class="legal-metadata"><div><span class="legal-meta-icon"><img src="${A('legal-file')}" alt=""></span><span>Phiên bản chính sách<strong>v1.0</strong></span></div><div><span class="legal-meta-icon"><img src="${A('legal-calendar')}" alt=""></span><span>Cập nhật gần nhất<strong>12/10/2026</strong></span></div></div><div class="legal-columns"><main class="legal-sections">${sections.map(([h,t],i)=>`<section class="legal-section" id="legal-section-${i+1}"><b>${i+1}</b><div><strong>${h}</strong><p>${t}</p></div></section>`).join('')}${!privacy?`<div class="legal-inline-note">ⓘ Nội dung trong tài liệu này là Placeholder để đội ngũ pháp lý rà soát và hoàn thiện.</div>`:''}</main><aside class="legal-toc">${toc.map((t,i)=>`<button class="${i===0?'active':''}" data-legal-anchor="${Math.min(i+1,sections.length)}">${i+1}. ${t}</button>`).join('')}</aside></div><div class="legal-disclaimer"><span>ⓘ</span> Đây là nội dung minh họa cho giao diện demo, không thay thế văn bản pháp lý chính thức của nhà cung cấp.</div></div>`}
const faq=[['Đăng nhập và tài khoản','Các câu hỏi về đăng nhập, OTP, quản lý tài khoản.'],['Gói lượt chơi','Thông tin các gói, quyền lợi và cách sử dụng.'],['Gia hạn và hủy gia hạn','Hướng dẫn gia hạn, hủy gia hạn qua SMS.'],['Giải đấu (Tournament)','Cách tham gia, thể lệ, kết quả và phần thưởng.'],['Điểm số và xếp hạng','Cách tính điểm, bảng xếp hạng và lịch sử.']];
function helpCenter(){const faqIcons=['help-login','help-packages','help-renew','help-tournament','help-ranking'];const descriptions=['Các câu hỏi về đăng nhập, OTP, quản lý tài khoản.','Thông tin về các gói, quyền lợi và cách sử dụng.','Hướng dẫn gia hạn, hủy gia hạn qua SMS.','Cách tham gia, thể lệ, kết quả và phần thưởng.','Cách tính điểm, bảng xếp hạng và lịch sử.'];return `<div class="support-page help-figma-v37">${supportHead('Trung tâm trợ giúp','Chúng tôi luôn sẵn sàng hỗ trợ bạn')}<div class="help-search-wrap"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7"><circle cx="11" cy="11" r="7"/><path d="m16 16 5 5"/></svg><input class="support-search" id="help-search" placeholder="Nhập vấn đề bạn cần hỗ trợ..."></div><div class="support-shortcuts"><button data-help-quick="0"><img src="${A('help-otp')}" alt=""> <span><strong>Lỗi OTP</strong><small>Không nhận được mã</small></span></button><button data-go="packages"><img src="${A('help-payment')}" alt=""><span><strong>Thanh toán</strong><small>Hướng dẫn gói cước</small></span></button><button data-go="smsGuide"><img src="${A('help-credit')}" alt=""><span><strong>Không nhận được lượt</strong><small>Kiểm tra giao dịch</small></span></button></div><div class="support-hero"><div><h2>Bạn cần<br>hỗ trợ gì?</h2><p>Tìm câu trả lời nhanh trong các câu hỏi thường gặp hoặc gửi yêu cầu hỗ trợ cho chúng tôi.</p></div><img src="${A('help-mascot-figma')}" alt="Nhân vật hỗ trợ WiiG"></div><div class="support-help-heading"><h3>Câu hỏi thường gặp</h3><button data-go="termsPrivacy">Xem tất cả ›</button></div><div id="help-faq">${faq.map(([t,x],i)=>`<div class="faq-row"><button data-faq="${i}"><img class="faq-topic-icon" src="${A(faqIcons[i]||'help-login')}" alt=""><span class="faq-topic-copy"><strong>${t}</strong><small>${descriptions[i]||''}</small></span><b>${state.faqOpen===i?'⌃':'⌄'}</b></button><p class="faq-answer" style="display:${state.faqOpen===i?'block':'none'}">${x} ${i===2?'<button data-go="smsGuide">Xem hướng dẫn SMS ›</button>':''}</p></div>`).join('')}</div><h3>Các kênh hỗ trợ khác</h3><div class="support-channels"><div class="support-channel-card"><img src="${A('help-provider')}" alt=""><strong>Hỗ trợ nhà mạng</strong><p>Liên hệ nhà mạng của bạn để được hỗ trợ thanh toán, gia hạn và hủy gói.</p><button data-go="smsGuide">Xem hướng dẫn ›</button></div><div class="support-channel-card"><img src="${A('help-chat')}" alt=""><strong>Liên hệ hỗ trợ</strong><p>Đội ngũ chăm sóc khách hàng luôn sẵn sàng giải đáp thắc mắc.</p><button data-action="supportContact">Gửi yêu cầu hỗ trợ ›</button></div></div></div>`}
function auth(){const otp=state.authStep==='otp';return `<div class="new-auth">
<div class="auth-brand"><img src="${A('wiig-logo')}" alt="WiiG"><span>Digital Play, Everyday Fun</span></div>
${otp?'<button class="auth-back" data-action="editphone" aria-label="Quay lại">‹</button>':''}
<img class="auth-illustration" src="${A('welcome-mascots')}" alt="Nhân vật WiiG và robot">
<h1>${otp?'Xác thực số điện thoại':'Chào mừng đến WiiG'}</h1>
<p class="auth-description">${otp?'Chúng tôi đã gửi mã xác thực (OTP) gồm 6 chữ số đến số điện thoại của bạn.':'Khám phá thế giới game giải trí hấp dẫn mỗi ngày, mọi lúc, mọi nơi.'}</p>
<div class="auth-form"><label>Số điện thoại</label><div class="phone-field"><span class="country-code"><img src="${A('flag-vn')}" alt="Việt Nam"> +84 <span class="down">⌄</span></span>${otp?`<strong>${esc(state.phone||'')}</strong><button class="text-link" data-action="editphone">Thay đổi</button>`:`<input id="phone-input" inputmode="tel" type="tel" placeholder="Nhập số điện thoại" value="${esc(state.phone)}" autocomplete="tel">`}</div>
${otp?`<div class="otp-label"><label>Nhập mã OTP</label><small>Mã gồm 6 chữ số</small></div><div class="otp-boxes" id="otp-boxes">${Array.from({length:6},(_,i)=>`<input class="otp-digit" inputmode="numeric" type="text" maxlength="1" aria-label="Số OTP ${i+1}" autocomplete="${i===0?'one-time-code':'off'}">`).join('')}</div>`:''}
<div class="auth-assurance"><img class="auth-shield-icon" src="${A('otp-shield')}" alt=""><span>${otp?'Mã OTP được bảo mật và chỉ có hiệu lực trong thời gian ngắn.':'Chúng tôi sử dụng số điện thoại để đăng nhập an toàn và bảo vệ tài khoản của bạn.'}</span></div>
${otp?'<p class="auth-resend">Gửi lại sau <strong id="otp-countdown">00:45</strong></p>':''}
<button class="btn purple block auth-submit" data-action="${otp?'verifyotp':'sendotp'}">${otp?'Xác nhận':'Nhận mã OTP'} →</button>
<p id="auth-error" class="error" role="alert"></p>
</div><p class="auth-terms">Tiếp tục đồng nghĩa với việc bạn đồng ý với<br><a href="#" data-go="termsPrivacy">Điều khoản sử dụng</a> và <a href="#" data-go="termsPrivacy">Chính sách bảo mật</a></p>
<p class="auth-demo-note">Mã OTP dùng thử: <b>123456</b> · Không gửi SMS thật</p>
</div>`}
function mygames(){if(!state.loggedIn){state.returnAfterLogin='mygames';state.authStep='phone';go('account');return ''}let list=games.filter(g=>state.played.includes(g.id));return `<div class="page-title"><button class="back" data-back>‹</button><div><h1>Game của tôi</h1><p>Lượt chơi còn lại: ${state.credits}</p></div></div><div class="promo mygames-promo"><img src="assets/coins-cutout.png" alt="Xu lượt chơi WiiG"><div><h3>${state.credits} lượt chơi</h3><p>Khám phá thêm nhiều trò chơi hấp dẫn</p></div><button class="btn purple" data-go="packages">Nạp lượt →</button></div>${section('Đã chơi')}${list.length?list.map(g=>`<div class="game-list-item"><img src="${gameArt(g)}" alt=""><div><h3>${g.name}</h3><p>${g.category}</p></div><button class="btn purple" data-play-game="${g.id}">Chơi</button></div>`).join(''):'<div class="empty">Bạn chưa chơi game nào.</div>'}${section('Game yêu thích')}${games.filter(g=>state.favorites.includes(g.id)).map(g=>`<div class="game-list-item"><img src="${gameArt(g)}" alt=""><div><h3>${g.name}</h3></div><button class="btn purple" data-detail="${g.id}">Xem</button></div>`).join('')||'<div class="empty">Chưa có game yêu thích.</div>'}`}
function history(){return walletHistory()}

function esc(t){return String(t).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function showModal(title,content,buttons=[['Đóng',()=>{}]]){const root=document.createElement('div');root.className='overlay';root.innerHTML=`<div class="dialog"><h2>${title}</h2><p>${content}</p><div class="buttons">${buttons.map(([name],i)=>`<button class="btn ${i===buttons.length-1?'purple':'ghost'}" data-modal="${i}">${name}</button>`).join('')}</div></div>`;document.body.appendChild(root);root.addEventListener('click',e=>{const b=e.target.closest('[data-modal]');if(b){const fn=buttons[Number(b.dataset.modal)][1];root.remove();fn()}else if(e.target===root)root.remove()})}
function requireAuth(next){if(state.loggedIn)return true;state.returnAfterLogin=next;state.authStep='phone';go('account');return false}
function play(){return requestPlay(state.game)}
function requestPlay(id){
 const g=games.find(x=>x.id===id); if(!g)return;
 state.game=g.id;
 if(!state.loggedIn){state.returnAfterLogin='play';state.authStep='phone';go('account');return;}
 const balance=Math.max(0,Number(state.credits)||0);
 if(balance<g.cost){showModal('Bạn chưa đủ lượt chơi',`Bạn cần ${g.cost} lượt để chơi ${g.name}, nhưng hiện có ${balance} lượt. Hãy nạp thêm lượt để tiếp tục.`,[['Để sau',()=>{}],['Nạp lượt',()=>go('packages')]]);return;}
 state.credits=balance-g.cost;
 state.played=Array.from(new Set([...(state.played||[]),g.id]));
 state.walletSpends=state.walletSpends||[];
 state.walletSpends.push({name:g.name,credits:g.cost,date:new Date().toLocaleDateString('vi-VN')});
 save();
 openGameFrame(g.id);
}
function openGameFrame(id){
 const g=games.find(x=>x.id===id);if(!g)return;
 state.game=g.id;save();
 // These games are known not to work in a cross-origin iframe. Open them directly
 // in a new tab and ensure no stale game overlay remains over the Portal.
 const externalTabGames = new Set(['fishing','2048','basketball','jewel']);
 if(externalTabGames.has(g.id)){
   document.querySelector('.hb-game-overlay')?.remove();
   document.body.classList.remove('hb-game-open');
   const opened = window.open(g.url,'_blank','noopener,noreferrer');
   if(!opened){
     showModal('Cho phép mở game','Trình duyệt đã chặn cửa sổ mới. Hãy cho phép pop-up cho trang Portal rồi nhấn Chơi lại, hoặc mở game bằng liên kết bên dưới.',[
       ['Đóng',()=>{}],
       ['Mở game',()=>{window.location.href=g.url;}]
     ]);
   }
   return;
 }

 document.querySelector('.hb-game-overlay')?.remove();
 const root=document.createElement('div');root.className='hb-game-overlay';root.setAttribute('role','dialog');root.setAttribute('aria-modal','true');root.setAttribute('aria-label','Đang chơi '+g.name);
 const bar=document.createElement('div');bar.className='hb-game-bar';
 const title=document.createElement('div');title.className='hb-game-title';title.textContent='🎮 '+g.name;
 const actions=document.createElement('div');actions.className='hb-game-actions';
 const external=document.createElement('a');external.href=g.url;external.target='_blank';external.rel='noopener noreferrer';external.textContent='Mở tab mới ↗';external.title='Mở game ở tab mới và đóng khung game này';external.addEventListener('click',()=>{root.remove();document.body.classList.remove('hb-game-open');document.removeEventListener('keydown',onKey)});
 const close=document.createElement('button');close.type='button';close.className='hb-game-close';close.innerHTML='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M6 6l12 12M18 6 6 18"/></svg><span>Đóng</span>';close.setAttribute('aria-label','Đóng game và quay về WiiG');
 actions.append(external,close);bar.append(title,actions);
 const frame=document.createElement('iframe');frame.src=g.url;frame.title=g.name;frame.allow='autoplay; fullscreen; gamepad; clipboard-read; clipboard-write';frame.allowFullscreen=true;frame.referrerPolicy='strict-origin-when-cross-origin';
 const hint=document.createElement('div');hint.className='hb-game-hint';hint.innerHTML='<span>Đang tải game… Nếu game không hiển thị, hãy chọn <b>Mở tab mới ↗</b> ở phía trên.</span>';
 root.append(bar,frame,hint);document.body.appendChild(root);document.body.classList.add('hb-game-open');
 const stop=()=>{root.remove();document.body.classList.remove('hb-game-open');document.removeEventListener('keydown',onKey)};
 const onKey=e=>{if(e.key==='Escape')stop()};close.addEventListener('click',stop);document.addEventListener('keydown',onKey);
 frame.addEventListener('load',()=>hint.classList.add('hb-game-hint-loaded'));
 close.focus();
}
function render(){const views={home,catalog,detail,tournament,leaderboard,rankGame,rankTournament,rankHistory,notifications,notificationDetail,smsGuide,termsPrivacy,helpCenter,packages,packageDetail,packageConfirm,packageProcessing,packageSuccess,wallet,walletHistory,account,mygames,history};const page=views[state.page]||home;$('#app').innerHTML=`<div class="shell ${state.page==='account'&&!state.loggedIn?'shell-auth':''} ${state.page==='account'&&state.loggedIn?'shell-profile':''}">${state.page==='packages'?packagesHeader():['account','wallet','walletHistory','leaderboard','rankGame','rankTournament','rankHistory','notifications','notificationDetail','smsGuide','termsPrivacy','helpCenter'].includes(state.page)?'':header()}<main class="content">${page()}</main>${state.page==='account'&&!state.loggedIn?'':nav()}</div>`;bind();bindOtp();save()}
function handleAction(action){
 if(action==='play'){requestPlay(state.game);return;}
 if(action==='favorite'){if(!state.loggedIn){state.returnAfterLogin='favorite';state.authStep='phone';go('account');return;}state.favorites=state.favorites||[];state.favorites=state.favorites.includes(state.game)?state.favorites.filter(x=>x!==state.game):[...state.favorites,state.game];save();render();return;}
 if(action==='editphone'){state.authStep='phone';render();return;}
 if(action==='sendotp'){
  const input=document.getElementById('phone-input');const phone=(input?.value||'').replace(/\D/g,'');
  const err=document.getElementById('auth-error');
  if(phone.length<9||phone.length>11){if(err)err.textContent='Vui lòng nhập số điện thoại hợp lệ.';return;}
  state.phone=phone;state.authStep='otp';save();render();return;
 }
 if(action==='verifyotp'){
  const otp=Array.from(document.querySelectorAll('.otp-digit')).map(x=>x.value).join('');
  const err=document.getElementById('auth-error');
  if(otp!=='123456'){if(err)err.textContent='Mã OTP chưa đúng. Hãy nhập 123456 để thử nghiệm.';return;}
  state.loggedIn=true;state.credits=Math.max(0,Number(state.credits)||0);save();
  const next=state.returnAfterLogin||'home';
  if(next==='play'){go('detail');showModal('Đăng nhập thành công',state.credits>0?'Bạn đã đăng nhập. Hãy nhấn Chơi ngay để bắt đầu.':'Bạn đã đăng nhập nhưng chưa có lượt chơi. Hãy nạp lượt trước khi chơi.',[['Đóng',()=>{}],...(state.credits>0?[]:[['Nạp lượt',()=>go('packages')]])]);}
  else if(next==='favorite'){go('detail');}
  else go(next==='mygames'?'mygames':next==='packages'?'packages':'home');
  return;
 }
 if(action==='continuePackage'){
  if(!state.packageTermsAccepted){showModal('Cần đồng ý điều khoản','Vui lòng tích chọn đồng ý với Điều khoản sử dụng và Chính sách bảo mật trước khi tiếp tục.',[['Đóng',()=>{}]]);return;}
  state.confirmTermsAccepted=false;save();go('packageConfirm');return;
 }
 if(action==='confirmPurchase'){
  if(!state.confirmTermsAccepted){showModal('Cần đồng ý điều khoản','Vui lòng tích chọn đồng ý với Điều khoản sử dụng và Chính sách bảo mật trước khi xác nhận.',[['Đóng',()=>{}]]);return;}
  state.paymentCode='TX-'+Date.now().toString().slice(-8);state.paymentDate=new Date().toLocaleString('vi-VN');state.paymentStage='processing';save();go('packageProcessing');return;
 }
 if(action==='completePurchase'){
  const p=purchaseSelected();state.credits=(Number(state.credits)||0)+p.count;state.transactions=state.transactions||[];state.transactions.push({credits:p.count,date:new Date().toLocaleDateString('vi-VN')});state.paymentStage='success';save();go('packageSuccess');return;
 }
 if(action==='supportContact'){showModal('Liên hệ hỗ trợ','Đây là bản prototype. Hãy tích hợp kênh hỗ trợ thực tế để gửi yêu cầu.',[['Đóng',()=>{}]]);return;}
}
function bindOtp(){const inputs=Array.from(document.querySelectorAll('.otp-digit'));inputs.forEach((input,i)=>{input.addEventListener('input',e=>{const v=e.target.value.replace(/\D/g,'');if(v.length>1){[...v.slice(0,6-i)].forEach((d,k)=>{if(inputs[i+k])inputs[i+k].value=d});inputs[Math.min(5,i+v.length-1)].focus()}else{input.value=v;if(v&&i<5)inputs[i+1].focus()}});input.addEventListener('keydown',e=>{if(e.key==='Backspace'&&!input.value&&i>0)inputs[i-1].focus()});input.addEventListener('paste',e=>{e.preventDefault();const v=e.clipboardData.getData('text').replace(/\D/g,'').slice(0,6);[...v].forEach((d,k)=>{inputs[k].value=d});inputs[Math.min(5,v.length)].focus()})});if(inputs.length)inputs[0].focus()}
function bind(){
document.querySelectorAll('[data-play-game]').forEach(b=>b.onclick=()=>requestPlay(b.dataset.playGame));

document.querySelectorAll('[data-detail-ranking]').forEach(b=>b.onclick=()=>{state.rankGame=state.game;rankNavigate('rankGame')});

document.querySelectorAll('[data-legal-anchor]').forEach(b=>b.onclick=()=>{document.getElementById('legal-section-'+b.dataset.legalAnchor)?.scrollIntoView({behavior:'smooth',block:'center'});document.querySelectorAll('[data-legal-anchor]').forEach(x=>x.classList.toggle('active',x===b))});

document.querySelectorAll('[data-support-back]').forEach(b=>b.onclick=()=>go(state.supportFrom||'account'));
document.querySelectorAll('[data-notice-tab]').forEach(b=>b.onclick=()=>{state.noticeTab=b.dataset.noticeTab;save();render()});
document.querySelectorAll('[data-notice-id]').forEach(b=>b.onclick=()=>{state.noticeId=Number(b.dataset.noticeId);state.noticeRead=state.noticeRead||[];if(!state.noticeRead.includes(state.noticeId))state.noticeRead.push(state.noticeId);state.supportFrom='notifications';go('notificationDetail')});
document.querySelectorAll('[data-notice-readall]').forEach(b=>b.onclick=()=>{state.noticeRead=noticeData.map(n=>n.id);save();render()});
document.querySelectorAll('[data-legal-tab]').forEach(b=>b.onclick=()=>{state.legalTab=b.dataset.legalTab;save();render()});
document.querySelectorAll('[data-faq]').forEach(b=>b.onclick=()=>{state.faqOpen=state.faqOpen===Number(b.dataset.faq)?-1:Number(b.dataset.faq);save();render()});
document.querySelectorAll('[data-help-quick]').forEach(b=>b.onclick=()=>{state.faqOpen=0;render()});
const helpSearch=document.querySelector('#help-search');if(helpSearch)helpSearch.oninput=()=>{const q=helpSearch.value.toLowerCase();document.querySelectorAll('.faq-row').forEach((r,i)=>r.style.display=(faq[i].join(' ').toLowerCase().includes(q)?'':'none'))};
document.querySelectorAll('[data-copy-sms]').forEach(b=>b.onclick=()=>showModal('Cú pháp SMS','Vui lòng xác nhận cú pháp và đầu số thực tế với nhà mạng trước khi gửi tin nhắn.'));

document.querySelectorAll('[data-rank-go]').forEach(b=>b.onclick=()=>rankNavigate(b.dataset.rankGo));
document.querySelectorAll('[data-rank-back]').forEach(b=>b.onclick=rankBack);
document.querySelectorAll('[data-rank-game]').forEach(b=>b.onclick=()=>{state.rankGame=b.dataset.rankGame;rankNavigate('rankGame')});
document.querySelectorAll('[data-rank-setting]').forEach(b=>b.onclick=()=>{state[b.dataset.rankSetting]=b.dataset.rankValue;save();render()});
const rankSelect=document.getElementById('rank-game-select');if(rankSelect)rankSelect.onchange=()=>{state.rankGame=rankSelect.value;save();render()};
const rankMore=document.querySelector('[data-rank-more]');if(rankMore)rankMore.onclick=()=>{rankMore.textContent='Đã hiển thị bảng xếp hạng';rankMore.disabled=true};
[['package-terms','packageTermsAccepted','.pd-continue'],['confirm-terms','confirmTermsAccepted','.pc-submit']].forEach(([id,key,selector])=>{const cb=document.getElementById(id),btn=document.querySelector(selector);if(cb&&btn){btn.disabled=!cb.checked;cb.addEventListener('change',()=>{state[key]=cb.checked;btn.disabled=!cb.checked;save()})}});document.querySelectorAll('.pd-terms a,.pc-terms a').forEach(a=>a.addEventListener('click',e=>{e.preventDefault();e.stopPropagation();state.supportFrom=state.page;go('termsPrivacy')}));document.querySelectorAll('[data-select-package]').forEach(b=>b.onclick=()=>{state.selectedPackage=Number(b.dataset.selectPackage);state.paymentStage='idle';state.packageTermsAccepted=false;state.confirmTermsAccepted=false;go('packageDetail')});document.querySelectorAll('[data-payment]').forEach(b=>b.onclick=()=>{state.paymentMethod=b.dataset.payment;save();render()});document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>{if(['notifications','smsGuide','termsPrivacy','helpCenter'].includes(b.dataset.go))state.supportFrom=state.page;if(b.dataset.go==='catalog'){state.category='Tất cả'}go(b.dataset.go)});document.querySelectorAll('[data-back]').forEach(b=>b.onclick=back);document.querySelectorAll('[data-detail]').forEach(b=>b.onclick=()=>{state.game=b.dataset.detail;go('detail')});document.querySelectorAll('[data-category]').forEach(b=>b.onclick=()=>{state.category=b.dataset.category;go('catalog')});document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>handleAction(b.dataset.action));document.querySelectorAll('[data-package]').forEach(b=>b.onclick=()=>{if(!requireAuth('packages'))return;const credits=Number(b.dataset.package);showModal('Xác nhận gói chơi',`Kích hoạt gói ${credits} lượt chơi demo? Không có giao dịch thật.`,[['Hủy',()=>{}],['Kích hoạt',()=>{state.credits+=credits;state.packageName=credits+' lượt';state.transactions.push({credits,date:new Date().toLocaleDateString('vi-VN')});save();go('account');showModal('Kích hoạt thành công',`Đã cộng ${credits} lượt vào tài khoản.`)}]])});document.querySelectorAll('[data-wallet-filter]').forEach(b=>b.onclick=()=>{state.walletFilter=b.dataset.walletFilter;save();render()});const search=$('#search');if(search){search.addEventListener('input',()=>{state.query=search.value;const list=games.filter(g=>(state.category==='Tất cả'||g.category===state.category)&&(!state.query||(g.name+' '+g.category).toLowerCase().includes(state.query.toLowerCase())));$('#catalog-grid').innerHTML=list.length?list.map(catalogCard).join(''):'<div class="empty">Không có game phù hợp.</div>';document.querySelectorAll('[data-detail]').forEach(b=>b.onclick=()=>{state.game=b.dataset.detail;go('detail')})})}const filter=$('#filters');if(filter){let startX=0,scrollStart=0,moved=false;filter.addEventListener('pointerdown',e=>{if(e.pointerType==='mouse'&&e.button===0){startX=e.clientX;scrollStart=filter.scrollLeft;moved=false}});filter.addEventListener('pointermove',e=>{if(e.buttons!==1||e.pointerType!=='mouse')return;const dx=e.clientX-startX;if(Math.abs(dx)>4)moved=true;if(moved)filter.scrollLeft=scrollStart-dx});filter.addEventListener('click',e=>{if(moved){e.stopPropagation();e.preventDefault();moved=false}},true);filter.addEventListener('wheel',e=>{if(filter.scrollWidth>filter.clientWidth){filter.scrollLeft+=e.deltaY;e.preventDefault()}},{passive:false})}}
render();
